public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segmentsList = new java.util.ArrayList<>();
    if (u == null) {
        return segmentsList;
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return segmentsList;
    }
    // Remove a leading slash if the path is absolute to avoid an empty leading segment
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }
    // Split on '/' and keep empty segments (including trailing empty segment)
    String[] rawSegments = rawPath.split("/", -1);
    for (String rawSegment : rawSegments) {
        String decodedSegment;
        if (decode) {
            try {
                decodedSegment = java.net.URLDecoder.decode(rawSegment, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (java.io.UnsupportedEncodingException e) {
                // UTF-8 is guaranteed to be supported; fallback to raw segment
                decodedSegment = rawSegment;
            }
        } else {
            decodedSegment = rawSegment;
        }
        segmentsList.add(new PathSegmentImpl(decodedSegment));
    }
    return segmentsList;
}

